@@ -0,0 +1,31 @@
+'use strict';
+
+const db = require('../../database');
+const batch = require('../../batch');
+
+module.exports = {
+	name: 'Migrate restricted chat settings to allow lists',
+	timestamp: Date.UTC(2025, 3, 16),
+	method: async function () {
+		const { progress } = this;
+		progress.total = await db.sortedSetCard('users:joindate');
+
+		await batch.processSortedSet('users:joindate', async (uids) => {
+			const settings = await db.getObjects(uids.map(uid => `user:${uid}:settings`));
+			const eligible = uids.reduce((result, uid, index) => {
+				const setting = settings[index] || {};
+				if (parseInt(setting.restrictChat, 10) === 1 && setting.chatAllowList === undefined) {
+					result.push(uid);
+				}
+				return result;
+			}, []);
+			const following = await db.getSortedSetsMembers(eligible.map(uid => `following:${uid}`));
+			const bulkSet = eligible.map((uid, index) => [
+				`user:${uid}:settings`,
+				{ chatAllowList: JSON.stringify(following[index].map(String)) },
+			]);
+			await db.setObjectBulk(bulkSet);
+			progress.incr(uids.length);
+		}, { batch: 500 });
+	},
+};
